 ('PV-001',  1, 'preparacao', 'Cadastros', 'Carga final de clientes, fornecedores e transportadoras em Produção', 'Cerca de 5.000 registros (amostra de ~500 já feita). Prazo acordado por e-mail em 21/10. Conferir duplicados e CNPJ/loja antes de liberar.', 'AMBOS', 'Cássio · Aline', '2026-11-04', '2026-11-19', 'em_andamento', 'alta', true, 'DIG-011 · GER-001', null),
 ('PV-002',  2, 'preparacao', 'Cadastros', 'Produtos com grupo, subgrupo e conta contábil', '194 produtos ativos sem grupo; regra da conta contábil do produto; flags faturável/bonificado na SB1 e base de comissão.', 'AMBOS', 'Cássio · Aline', '2026-11-04', '2026-11-19', 'em_andamento', 'alta', true, 'DIG-010', null),
 ('PV-003',  3, 'preparacao', 'Cadastros', 'De-para dos itens do Datasul pela natureza de PIS/COFINS', 'O mesmo serviço existe em dois códigos (ex.: 00000108 cumulativo × 00000020 não cumulativo). A separação software × equipamento/locação tem que sobreviver à carga, porque define a tributação.', 'AMBOS', 'Vanessa · Jehssica', '2026-11-04', '2026-11-19', 'planejado', 'alta', true, 'Regime PIS/COFINS', 'PV-002'),
