 ('PV-006',  6, 'preparacao', 'Cadastros', 'Código inteligente, EAN automático GS1 e associação do MAC', 'Prazos de 05/10 vencidos. Sem isso a carga de produtos novos fica travada; o e-mail do Maurício sobre o código inteligente está sem resposta.', 'AMBOS', 'Maicon · Daniel', '2026-11-04', '2026-11-19', 'bloqueado', 'alta', false, 'CAD-001 · CAD-002 · CAD-003 · CAD-004', null),
 ('PV-007',  7, 'preparacao', 'Cadastros', 'Estrutura e configurador com uma família real de produto', 'Validar tamanho de B1_COD/B1_DESC com uma família real (cadastros genéricos em todos os treinamentos).', 'CLIENTE', 'PCP Dígitro · Daniel', '2026-11-09', '2026-11-27', 'planejado', 'media', false, null, null),
 ('PV-008',  8, 'preparacao', 'Cadastros', 'Recursos (matrícula × centro de custo) e roteiros para o apontamento do Redmine', 'Recurso = matrícula ligada ao CC (ex.: 93470), calendário de 8 h, roteiro do produto LC0031.', 'AMBOS', 'Daniel · Viviani', '2026-11-09', '2026-11-27', 'planejado', 'media', false, 'Custo em Partes', null),
 ('PV-009',  9, 'preparacao', 'Cadastros', 'Tabelas de preço (DA0/DA1) importadas e enviadas ao CRM', '7 tabelas e 322 itens; importação no CRM iniciada em 03/11. Definir quem mantém a tabela depois da virada.', 'AMBOS', 'Fábio · Aline', '2026-11-03', '2026-11-13', 'em_andamento', 'alta', true, null, null),
 ('PV-010', 10, 'preparacao', 'GFE', 'Transportadoras, faixas de CEP e tabelas de frete AT/Alfa', 'Em 14/10 só 2 de 7 transportadoras estavam cadastradas. Junto, a massa de CT-e/XML para o teste do GFE.', 'CLIENTE', 'Logística Dígitro · Jonatan', '2026-11-04', '2026-11-19', 'planejado', 'alta', true, 'DIG-006', null),
 ('PV-011', 11, 'preparacao', 'Fiscal', 'Regras do Configurador de Tributos em Produção', 'Levar as regras faltantes do Teste para a Produção (comparativo de 30/10; função Transferir da aba Tributos) e conferir de novo depois de cada carga: em 14/10 uma sobreposição de base apagou perfis e TTD.', 'TOTVS', 'Vanessa', '2026-11-04', '2026-11-20', 'em_andamento', 'alta', true, 'Aba Tributos', null),
